function modal(title,body,footer='',onSubmit){const d=$('#dialog');d.innerHTML=`<form id="modal-form"><div class="dialog-header"><h2 id="dialog-title">${esc(title)}</h2><button class="iconbtn" type="button" data-action="close" aria-label="닫기">${icon('close')}</button></div><div class="dialog-body">${body}</div><div class="dialog-footer">${footer||'<button type="button" class="btn" data-action="close">닫기</button>'}</div></form>`;if(onSubmit)$('#modal-form').onsubmit=e=>{e.preventDefault();onSubmit(new FormData(e.currentTarget));};if(!d.open)d.showModal();}
const formButtons=(label='저장')=>`<button class="btn" type="button" data-action="close">취소</button><button class="btn primary" type="submit">${icon('check')}${esc(label)}</button>`;
function login(){return `<main class="login"><section class="login-story">${logo()}<div class="story-copy"><div class="eyebrow">CONNECT EVERY STEP.</div><h1>설비의 시작부터,<br>납품 그 너머까지.<br><em>모든 공정을 하나로.</em></h1><p>설계, 제작, 시운전 그리고 고객의 현장까지.<br>흩어진 일정을 잇고, 함께 만드는 내일을 봅니다.</p></div><svg class="machine-art" viewBox="0 0 600 260" fill="none" role="img" aria-label="원단이 롤러를 따라 연결되는 롤투롤 설비의 개념도"><defs><linearGradient id="web" x1="0" y1="0" x2="600" y2="0"><stop stop-color="#b9d79e"/><stop offset="1" stop-color="#739b79"/></linearGradient></defs><g stroke="#6b947c" stroke-width="1"><path d="M15 218h570 M40 235h70 M490 235h70 M50 185v50 M540 185v50 M190 165v70 M410 165v70"/><path d="M40 197v-87a40 40 0 0 1 80 0v87 M480 197v-87a40 40 0 0 1 80 0v87"/></g><path d="M80 79h100l35 66h170l35-66h100" stroke="url(#web)" stroke-width="12"/><g stroke="#cee4b5" stroke-width="1.5"><circle cx="80" cy="120" r="46" fill="#244d3e"/><circle cx="80" cy="120" r="34"/><circle cx="80" cy="120" r="22"/><circle cx="80" cy="120" r="8" fill="#cee4b5"/><circle cx="520" cy="120" r="46" fill="#244d3e"/><circle cx="520" cy="120" r="34"/><circle cx="520" cy="120" r="22"/><circle cx="520" cy="120" r="8" fill="#cee4b5"/><circle cx="180" cy="90" r="12" fill="#244d3e"/><circle cx="215" cy="145" r="15" fill="#244d3e"/><circle cx="385" cy="145" r="15" fill="#244d3e"/><circle cx="420" cy="90" r="12" fill="#244d3e"/></g><rect x="248" y="77" width="104" height="49" rx="5" stroke="#90b295" fill="#234b3e"/><path d="M263 92h74 M263 102h74 M276 126v13 M324 126v13" stroke="#90b295"/><path d="m290 55 10 7 10-7" stroke="#cce5ae"/><path d="M300 34v26" stroke="#cce5ae"/><text x="247" y="196" fill="#a7c5ac" font-family="Manrope,sans-serif" font-size="9" letter-spacing="3">ROLL TO ROLL</text><g stroke="#557e66" stroke-dasharray="3 5"><path d="M80 20v177 M520 20v177"/></g></svg><div class="story-foot"><span>BATTERY EQUIPMENT · PROJECT LIFECYCLE</span><span>DESIGNED FOR PEOPLE.</span></div></section><section class="login-main"><div class="entry"><div class="eyebrow">YOUR CONNECTED WORKSPACE</div><h2>오늘의 업무를 시작해 볼까요?</h2><p>나에게 편한 화면으로, 중요한 일에 집중하세요.</p><form id="entry-form"><label>체험할 이름<input name="name" value="김민수" required maxlength="30" autocomplete="name" placeholder="이름을 입력하세요"></label><label>어떤 화면이 편하신가요?</label><div class="mode-choices"><button type="button" class="mode-choice ${entryMode==='easy'?'selected':''}" data-action="entry-mode" data-mode="easy" aria-pressed="${entryMode==='easy'}">${icon('wrench')}<strong>현장용 쉬운 화면</strong><small>큰 글씨와 버튼으로<br>내 작업과 문제만 간편하게</small></button><button type="button" class="mode-choice ${entryMode==='manager'?'selected':''}" data-action="entry-mode" data-mode="manager" aria-pressed="${entryMode==='manager'}">${icon('chart')}<strong>관리용 상세 화면</strong><small>프로젝트부터 도면까지<br>전체 현황을 세밀하게</small></button></div><button class="btn primary start" type="submit">체험 시작하기 ${icon('arrow')}</button></form><a class="btn signin" href="/signin-with-chatgpt?return_to=%2F" target="_top">${icon('user')}ChatGPT로 로그인</a><div class="entry-note">샘플 프로젝트를 사용하는 체험 공간입니다. 입력한 내용은 이 브라우저에 저장됩니다. 화면 선택은 사용 편의를 위한 설정이며 언제든 바꿀 수 있습니다.</div><div class="entry-footer"><span>© 2026 CELLINK PLM</span><span>사람을 위한, 쉬운 설비 관리</span></div></div></section></main>`;}
const navItems=[['dashboard','home','통합 현황'],['projects','folder','프로젝트'],['schedule','chart','일정 · 간트 차트'],['issues','issue','이슈 관리'],['weekly','report','주간 현황 요약'],['docs','file','도면 · 문서'],['bom','box','부품 구성 · BOM'],['changes','change','설계 변경 · 승인'],['import','upload','엑셀 가져오기']];
function frame(body){const easy=mode==='easy';const n=navItems.find(n=>n[0]===view);const nav=easy?[['dashboard','home','오늘 할 일'],['schedule','calendar','내 작업 일정'],['issues','issue','문제 확인'],['docs','file','도면 보기']]:navItems;return `<div class="${easy?'easy':''}"><aside class="sidebar">${logo()}<div class="workspace-switch"><span class="workspace-icon">${icon('factory')}</span><span><strong>이차전지 설비사업부</strong><small>제작에서 납품까지, 함께</small></span></div><div class="nav-label">WORKSPACE</div><nav class="nav">${nav.map(([id,ic,label])=>`<button data-nav="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ic)}${label}${id==='issues'?`<span class="count">${db.issues.filter(i=>i.status!=='해결').length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="nav-divider"></div><nav class="nav"><button data-nav="help">${icon('help')}사용 안내</button></nav><div class="mode-panel"><div class="mode-name">${icon(easy?'wrench':'chart')}${easy?'현장용 쉬운 화면':'관리용 상세 화면'}</div><p>${easy?'큰 글씨로 내 업무에 집중해요':'전체 업무를 한눈에 관리해요'}</p><button class="mode-toggle" data-action="switch-mode">${easy?'관리용 상세 화면':'현장용 쉬운 화면'}으로 전환 ${icon('arrow')}</button></div><div class="sidebar-user"><span class="avatar">${esc(user.name.slice(0,1))}</span><div><strong>${esc(user.name)}</strong><small>${easy?'현장 작업 · 체험':'프로젝트 관리 · 체험'}</small></div><button class="iconbtn" data-action="logout" aria-label="체험 종료">${icon('logout')}</button></div></div></aside><div class="shell"><header class="topbar"><div class="breadcrumb"><button class="iconbtn mobile-menu" data-action="menu" aria-label="메뉴 열기">${icon('menu')}</button><span>워크스페이스</span><span>/</span><strong>${easy&&view==='dashboard'?'오늘 할 일':n?.[2]||'사용 안내'}</strong></div><div class="top-right"><form id="global-search" class="top-search">${icon('search')}<input name="q" aria-label="전체 검색" placeholder="프로젝트, 이슈 검색"><kbd>↵</kbd></form><span class="demo-label">DEMO WORKSPACE</span><span class="today num">${TODAY.replaceAll('-','.')} <span class="muted">${['일','월','화','수','목','금','토'][new Date(TODAY+'T12:00:00').getDay()]}</span></span><button class="iconbtn bell" data-action="notifications" aria-label="확인이 필요한 업무">${icon('bell')}</button><span class="avatar">${esc(user.name.slice(0,1))}</span></div></header><main class="content">${body}<footer class="page-footer"><span><i class="dot"></i>브라우저 저장 · 샘플 데이터 기반 체험</span><span>CELLINK PLM &nbsp; / &nbsp; CONNECT EVERY STEP.</span></footer></main></div></div>`;}
function pageHead(kicker,title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><div class="head-actions">${actions}</div></div>`;}
function projectSelect(){return `<div class="project-filter"><select id="project-select" aria-label="프로젝트 선택">${projectOptions(project,true)}</select></div>`;}
const overviewTools=()=>`<div class="overview-tools">${projectSelect()}<span class="sync">${icon('checkcircle')} 현재 브라우저 데이터 기준</span></div>`;
function metrics(){const ps=currentProjects(),ts=currentTasks(),is=currentIssues();const active=ps.filter(p=>percent(p.id)<100).length,delayed=ts.filter(late).length,unresolved=is.filter(i=>i.status!=='해결').length;const end=dateAdd(weekStart(TODAY),6);const due=ps.filter(p=>p.due>=weekStart(TODAY)&&p.due<=end).length;return `<div class="metrics">${[
 ['진행 중 프로젝트',active,'건','folder',`전체 ${ps.length}개 프로젝트`,'모든 공정을 연결해요','M0 25 10 23 20 25 30 15 40 17 50 9 60 12 70 4'],
 ['지연된 작업',delayed,'건','clock',`${ps.filter(p=>projectState(p)==='지연').length}개 프로젝트`,'확인이 필요해요','M0 12 10 15 20 8 30 12 40 7 50 11 60 5 70 7'],
 ['미해결 이슈',unresolved,'건','issue',`우선 확인 ${is.filter(i=>i.status!=='해결'&&i.severity==='높음').length}건`,'함께 해결해요','M0 8 10 14 20 11 30 19 40 15 50 23 60 19 70 25'],
 ['이번 주 납품 예정',due,'건','box',`${shortDate(weekStart(TODAY))} – ${shortDate(end)}`,'출하 일정을 확인해요','M0 27 10 27 20 20 30 20 40 13 50 13 60 5 70 5']
 ].map(([title,v,unit,ic,a,b,path],idx)=>`<div class="metric"><div class="metric-top">${title}<span class="metric-icon ${idx===1?'warn':''}">${icon(ic)}</span></div><div class="metric-value">${v}<small>${unit}</small></div><div class="metric-bottom"><b class="${idx===1?'red':''}">${esc(a)}</b><span>· ${b}</span></div><svg class="metric-spark" viewBox="0 0 70 32" fill="none" aria-hidden="true"><path d="${path} L70 32H0Z" fill="${idx===1?'#f9ece4':'#eff5e9'}"/><path d="${path}" stroke="${idx===1?'#d59b7d':'#9dbb84'}" stroke-width="1.5"/></svg></div>`).join('')}</div>`;}
function compactTimeline(){const start=dateAdd(weekStart(TODAY),-14);const total=35;return `<div class="panel"><div class="panel-header"><div class="panel-title"><h2>프로젝트 일정</h2><span class="tally num">${currentProjects().length}</span></div><button class="link" data-nav="schedule">전체 일정 보기 ${icon('chevron')}</button></div><div class="timeline-wrap"><div class="project-timeline"><div class="timeline-head"><span>프로젝트 / 공정 현황</span>${Array.from({length:5},(_,i)=>`<span class="num">${shortDate(dateAdd(start,i*7))}</span>`).join('')}</div><div class="timeline-body">${currentProjects().map((p,i)=>{const ts=db.tasks.filter(t=>t.project===p.id);const t=ts.find(late)||ts.find(t=>t.progress>0&&t.progress<100)||ts.find(t=>t.progress<100)||ts.at(-1);const s=t?Math.max(0,Math.min(total-1,days(start,t.start))):0;const width=t?Math.max(1,Math.min(total-s,days(start,t.end)+1-s)):1;return `<div class="timeline-row" data-project="${esc(p.id)}" tabindex="0" role="button" aria-label="${esc(p.name)} 상세 보기"><div class="timeline-label"><strong>${esc(p.name)} ${p.market==='수출'?`<span class="tag blue" style="padding:1px 4px;font-size:8px">수출</span>`:''}</strong><small>${esc(p.customer)} · ${esc(p.equipment)} · ${percent(p.id)}%</small></div><div class="timeline-track" style="--today-x:${(days(start,TODAY)+0.5)/total*100}%"><span class="schedule-bar ${t&&late(t)?'delay':i===2?'blue':i>2?'gray':''}" style="left:${Math.min(93,s/total*100)}%;width:${Math.max(7,width/total*100)}%;--progress:${t?.progress||0}%"><span>${esc(t?.stage||'계획')}</span><span>${t&&late(t)?`+${lateDays(t)}일`:t?.progress?`${t.progress}%`:''}</span></span></div></div>`;}).join('')}</div><div class="timeline-foot"><span class="legend"><i></i>진행</span><span class="legend"><i class="orange"></i>지연</span><span class="legend"><i class="blue"></i>예정</span><span class="today-line">┆ 오늘 ${shortDate(TODAY)}</span></div></div></div></div>`;}
function quickSummary(){const is=currentIssues();const dl=currentTasks().filter(late);const resolved=is.filter(i=>i.resolved>=weekStart(TODAY)&&i.resolved<=TODAY).length;return `<aside class="panel summary-panel"><div class="panel-header"><div class="panel-title">${icon('sparkle','summary-icon')}<h2>이번 주, 한눈에</h2></div><span class="tag" style="background:#e1ebd4;color:#7c925f;font-size:8px">WEEKLY</span></div><div class="panel-body"><div class="week-label"><span>${shortDate(weekStart(TODAY))} – ${shortDate(dateAdd(weekStart(TODAY),6))}</span><span>데이터 기반 초안</span></div><h3>지금 확인하면,<br>다음 공정이 순조로워집니다.</h3><div class="summary-items"><div class="summary-item"><i class="dot"></i><div><strong>지연 작업 ${dl.length}건</strong><br>${dl.length?`${esc(pName(dl[0].project))} · ${esc(dl[0].stage)} 확인이 필요합니다.`:'등록된 작업은 계획 일정 내에 있습니다.'}</div></div><div class="summary-item"><i class="dot"></i><div><strong>우선 확인 이슈 ${is.filter(i=>i.severity==='높음'&&i.status!=='해결').length}건</strong><br>담당자와 조치 기한을 점검하세요.</div></div><div class="summary-item"><i class="dot"></i><div><strong>이번 주 이슈 ${resolved}건 해결</strong><br>완료된 조치와 다음 주 계획을 확인하세요.</div></div></div><button class="btn" data-nav="weekly">주간 현황 자세히 보기 ${icon('arrow')}</button><div class="summary-foot">데이터를 바탕으로 정리했어요. 최종 확인은 담당자에게.</div></div></aside>`;}
function issueTable(rows,compact=false){if(!rows.length)return empty('조건에 맞는 이슈가 없습니다.','checkcircle');return `<div class="table-wrap"><table><thead><tr><th>이슈 내용</th><th>중요도</th><th>담당자</th>${compact?'':'<th>기한</th>'}<th>상태</th></tr></thead><tbody>${rows.map(i=>`<tr class="clickable" data-issue="${esc(i.id)}" tabindex="0" role="button" aria-label="${esc(i.title)} 상세 보기"><td class="title-cell"><strong>${esc(i.title)}</strong><span class="subline">${esc(pName(i.project))} · ${esc(i.id)}</span></td><td><span class="priority ${i.severity==='높음'?'high':i.severity==='보통'?'middle':''}">${esc(i.severity)}</span></td><td>${person(i.owner)}</td>${compact?'':`<td class="num ${i.due<TODAY&&i.status!=='해결'?'red':''}">${shortDate(i.due)}</td>`}<td>${badge(i.status)}</td></tr>`).join('')}</tbody></table></div>`;}
function activities(){return `<aside class="panel"><div class="panel-header"><div class="panel-title"><h2>최근 업데이트</h2></div><span class="muted" style="font-size:9px">ACTIVITY</span></div><div class="activity-list">${db.logs.slice(0,3).map(l=>`<div class="activity"><span class="activity-icon">${icon(l.type)}</span><div class="activity-text">${esc(l.text)}<small>${shortDate(l.date)} · 워크스페이스</small></div></div>`).join('')}</div></aside>`;}
function dashboard(){return pageHead('WORKSPACE OVERVIEW','전체 흐름을, 한눈에.','진행 상황부터 놓치기 쉬운 이슈까지, 오늘의 프로젝트를 확인하세요.',`<button class="btn" data-nav="import">${icon('upload')}엑셀 가져오기</button><button class="btn primary" data-action="new-project">${icon('plus')}프로젝트 만들기</button>`)+overviewTools()+metrics()+`<div class="grid-main">${compactTimeline()}${quickSummary()}</div><div class="grid-bottom"><section class="panel"><div class="panel-header"><div class="panel-title"><h2>확인이 필요한 이슈</h2><span class="tally num">${currentIssues().filter(i=>i.status!=='해결').length}</span></div><button class="link" data-nav="issues">전체 이슈 ${icon('chevron')}</button></div>${issueTable(currentIssues().filter(i=>i.status!=='해결').sort((a,b)=>(a.severity==='높음'?-1:1)-(b.severity==='높음'?-1:1)).slice(0,4),true)}</section>${activities()}</div>`;}
function empty(text,ic='folder'){return `<div class="blank">${icon(ic)}${esc(text)}</div>`;}
function projectsPage(){let ps=currentProjects().filter(p=>(projectMarket==='all'||p.market===projectMarket)&&(!filterText||`${p.name} ${p.customer} ${p.id} ${p.owner}`.includes(filterText)));if(detailProject)return projectDetail(detailProject);return pageHead('PROJECT PORTFOLIO','프로젝트','설비 제작부터 고객 현장 인도까지, 프로젝트의 모든 단계를 연결합니다.',`<button class="btn primary" data-action="new-project">${icon('plus')}프로젝트 만들기</button>`)+`<div class="toolbar"><input class="search" id="page-search" aria-label="프로젝트 검색" placeholder="프로젝트명, 고객사, 담당자 검색" value="${esc(filterText)}"><select id="market-filter" aria-label="납품 구분">${options([{value:'all',label:'내수 · 수출 전체'},'내수','수출'],projectMarket)}</select><span class="muted" style="font-size:12px">${ps.length}개 프로젝트</span></div><div class="projects-grid">${ps.map(p=>`<article class="project-card" data-project="${esc(p.id)}" role="button" tabindex="0" aria-label="${esc(p.name)} 상세"><div class="project-card-top"><span class="num">${esc(p.id)}</span>${badge(projectState(p))}</div><div class="project-symbol">${icon('factory')}</div><h2>${esc(p.name)}</h2><p>${esc(p.customer)} · ${esc(p.equipment)} · ${esc(p.country)}</p><div style="display:flex;justify-content:space-between;margin-top:25px;font-size:11px"><span class="muted">전체 공정 진행률</span><strong class="num green">${percent(p.id)}%</strong></div><div class="progress-line"><i style="width:${percent(p.id)}%"></i></div><div class="project-card-meta"><span>미해결 이슈 <strong>${db.issues.filter(i=>i.project===p.id&&i.status!=='해결').length}</strong></span><span>지연 작업 <strong>${db.tasks.filter(t=>t.project===p.id&&late(t)).length}</strong></span></div><div class="project-card-footer"><span>${person(p.owner)}</span><span>${badge(p.market)} &nbsp; 납품 ${shortDate(p.due)}</span></div></article>`).join('')}</div>${!ps.length?empty('검색 결과가 없습니다.'):''}`;}
function projectDetail(id){const p=db.projects.find(p=>p.id===id);if(!p)return empty('프로젝트를 찾을 수 없습니다.');const ts=db.tasks.filter(t=>t.project===id);return pageHead('PROJECT DETAILS',esc(p.name),`${esc(p.id)} · ${esc(p.customer)} · ${esc(p.equipment)}`,`<button class="btn" data-action="projects-back">${icon('folder')}목록으로</button><button class="btn primary" data-action="edit-project" data-id="${esc(p.id)}">${icon('edit')}정보 수정</button>`)+`<div class="detail-banner"><div>${badge(p.market)} ${badge(projectState(p))}<h2>${esc(p.customer)} · ${esc(p.country)}</h2><p>${p.start} – ${p.due} · PM ${esc(p.owner)}</p></div><div class="banner-stats"><div class="banner-stat"><small>진행률</small><strong>${percent(id)}%</strong></div><div class="banner-stat"><small>지연 작업</small><strong>${ts.filter(late).length}</strong></div><div class="banner-stat"><small>미해결 이슈</small><strong>${db.issues.filter(i=>i.project===id&&i.status!=='해결').length}</strong></div></div></div><div class="toolbar"><button class="btn" data-action="project-go" data-page="schedule" data-id="${esc(id)}">${icon('chart')}간트 차트</button><button class="btn" data-action="project-go" data-page="issues" data-id="${esc(id)}">${icon('issue')}관련 이슈</button><button class="btn" data-action="project-go" data-page="docs" data-id="${esc(id)}">${icon('file')}도면 · 문서</button><button class="btn" data-action="project-go" data-page="bom" data-id="${esc(id)}">${icon('box')}부품 구성</button><button class="btn" data-action="new-task" data-project="${esc(id)}">${icon('plus')}작업 등록</button></div><section class="panel"><div class="panel-header"><div class="panel-title"><h2>작업 및 마일스톤</h2></div></div>${taskTable(ts)}</section>`;}
function taskTable(ts){return !ts.length?empty('등록된 작업이 없습니다. 작업을 추가해 주세요.','calendar'):`<div class="table-wrap"><table><thead><tr><th>공정 / 작업명</th><th>담당자</th><th>계획 기간</th><th>진행률</th><th>상태</th></tr></thead><tbody>${ts.map(t=>`<tr class="clickable" data-task="${esc(t.id)}" tabindex="0" role="button" aria-label="${esc(t.name)} 수정"><td class="title-cell"><strong>${esc(t.name)}</strong><span class="subline">${esc(t.stage)} · ${esc(pName(t.project))}${t.predecessor?' · 선행 '+esc(t.predecessor):''}</span></td><td>${person(t.owner)}</td><td class="num">${shortDate(t.start)} – ${shortDate(t.end)}</td><td><strong class="num">${t.progress}%</strong></td><td>${badge(t.progress===100?'완료':late(t)?'지연':t.progress>0?'진행 중':'예정')}${late(t)?`<small class="red"> +${lateDays(t)}일</small>`:''}</td></tr>`).join('')}</tbody></table></div>`;}
function schedulePage(){return pageHead('PROJECT SCHEDULE','일정 · 간트 차트','막대를 선택해 작업을 수정하세요. 지연은 계획 종료일과 진행률로 계산합니다.',`<button class="btn" data-action="schedule-export">${icon('download')}일정 내보내기</button><button class="btn primary" data-action="new-task">${icon('plus')}작업 등록</button>`)+overviewTools()+`<section class="panel" style="margin-bottom:22px"><div class="panel-header"><div class="panel-title"><h2>공정별 일정</h2><span class="tally">${currentTasks().length}개 작업</span></div><div class="segmented"><button data-action="gantt-view" data-value="Week" class="${ganttView==='Week'?'active':''}">주간</button><button data-action="gantt-view" data-value="Month" class="${ganttView==='Month'?'active':''}">월간</button></div></div><div class="gantt-host" id="gantt"></div><div class="timeline-foot"><span class="legend"><i></i>진행 / 예정</span><span class="legend"><i class="orange"></i>계획 종료일 초과</span><span class="today-line">오늘 ${TODAY} · 일정 변경은 작업 창에서 저장</span></div></section><section class="panel"><div class="panel-header"><div class="panel-title"><h2>작업 목록</h2></div></div>${taskTable(currentTasks())}</section>`;}
function mountGantt(){const el=$('#gantt');if(!el)return;const ts=currentTasks();if(!ts.length){el.innerHTML=empty('작업을 등록하면 간트 차트가 표시됩니다.');return;}if(typeof Gantt==='undefined'){el.innerHTML=`<div class="schedule-fallback">${ts.map(t=>`<div class="task-mini-row"><button class="link" data-action="edit-task" data-id="${esc(t.id)}">${esc(t.name)}</button><div class="task-mini-track"><i style="left:${Math.max(0,days('2026-10-01',t.start)/100*100)}%;width:${Math.min(100,Math.max(2,days(t.start,t.end)+1))}%"></i></div><span>${shortDate(t.start)} – ${shortDate(t.end)}</span></div>`).join('')}</div>`;return;}
 const ids=new Set(ts.map(t=>t.id));gantt=new Gantt(el,ts.map(t=>({id:t.id,name:`${pName(t.project)} · ${t.name}`,start:t.start,end:t.end,progress:Number(t.progress),dependencies:ids.has(t.predecessor)?t.predecessor:'',custom_class:late(t)?'delayed':''})),{view_mode:ganttView,language:'ko',readonly:true,bar_height:25,padding:20,column_width:ganttView==='Week'?120:170,container_height:500,scroll_to:TODAY,popup:false,on_click:t=>taskForm(t.id)});
 // Read-only bars keep planning changes explicit in the editable task form.
 el.querySelectorAll('.bar-wrapper').forEach(b=>{b.setAttribute('tabindex','0');b.setAttribute('role','button');b.setAttribute('aria-label',(ts.find(t=>t.id===b.dataset.id)?.name||'작업')+' 수정');b.addEventListener('dblclick',()=>taskForm(b.dataset.id));b.addEventListener('keydown',e=>{if(e.key==='Enter')taskForm(b.dataset.id);});b.addEventListener('click',()=>taskForm(b.dataset.id));});
}
function issuesPage(){let rows=currentIssues().filter(i=>(issueStatus==='all'||i.status===issueStatus)&&(issueOwner==='all'||i.owner===issueOwner)&&(issueCategory==='all'||i.category===issueCategory)&&(!filterText||`${i.title} ${i.description} ${pName(i.project)} ${i.owner}`.includes(filterText)));return pageHead('ISSUE TRACKER',mode==='easy'?'문제 확인':'이슈 관리','작은 문제도 놓치지 않도록, 등록부터 해결까지 함께 확인합니다.',`<button class="btn" data-action="extract">${icon('sparkle')}메모에서 추출</button><button class="btn primary" data-action="new-issue">${icon('plus')}${mode==='easy'?'문제 등록':'이슈 등록'}</button>`)+`<div class="toolbar">${projectSelect()}<input id="page-search" class="search" placeholder="이슈 내용, 담당자 검색" aria-label="이슈 검색" value="${esc(filterText)}"><select id="issue-status" aria-label="이슈 상태">${options([{value:'all',label:'전체 상태'},'접수','조치 중','해결'],issueStatus)}</select><select id="issue-owner" aria-label="담당자">${options([{value:'all',label:'전체 담당자'},...new Set(db.issues.map(i=>i.owner))],issueOwner)}</select><select id="issue-category" aria-label="분류">${options([{value:'all',label:'전체 분류'},'품질','납기','사양','안전','기타'],issueCategory)}</select><div class="segmented"><button data-action="issue-layout" data-value="list" class="${issueLayout==='list'?'active':''}">목록</button><button data-action="issue-layout" data-value="board" class="${issueLayout==='board'?'active':''}">보드</button></div></div>${issueLayout==='list'?`<section class="panel">${issueTable(rows)}</section>`:`<div class="kanban">${['접수','조치 중','해결'].map(s=>`<section class="kanban-column"><div class="kanban-heading">${badge(s)}<small>${rows.filter(i=>i.status===s).length}</small></div>${rows.filter(i=>i.status===s).map(i=>`<article class="issue-card" data-issue="${esc(i.id)}" role="button" tabindex="0" aria-label="${esc(i.title)} 상세"><div style="display:flex;justify-content:space-between">${badge(i.severity)}<small>${esc(i.id)}</small></div><h3>${esc(i.title)}</h3><p class="muted" style="font-size:11px;margin-bottom:17px">${esc(pName(i.project))}</p><div class="issue-card-footer">${person(i.owner)}<span>${shortDate(i.due)}까지</span></div></article>`).join('')}</section>`).join('')}</div>`}`;}
function reportKey(){return project+'|'+reportDate;}
function generateReport(){const start=reportDate,end=dateAdd(start,6),ps=currentProjects(),ts=currentTasks(),is=currentIssues();const due=ps.filter(p=>p.due>=start&&p.due<=end);const newIssues=is.filter(i=>i.created>=start&&i.created<=end);const resolved=is.filter(i=>i.resolved>=start&&i.resolved<=end);const delayed=ts.filter(t=>t.progress<100&&t.end<TODAY);const next=ts.filter(t=>t.start<=dateAdd(end,7)&&t.end>=dateAdd(end,1)&&t.progress<100);return `1. 전체 진행 현황\n${ps.length}개 프로젝트를 관리하고 있습니다. 진행률은 등록된 작업의 단순 평균입니다.\n${ps.map(p=>`• ${p.name}: ${percent(p.id)}% · 납품 예정 ${p.due} · PM ${p.owner}`).join('\n')}\n\n2. 지연 및 확인이 필요한 작업 (현재 ${TODAY} 기준)\n${delayed.length?delayed.map(t=>`• ${pName(t.project)} / ${t.name}: 계획 종료 ${t.end}, ${lateDays(t)}일 초과, 진행 ${t.progress}% · 담당 ${t.owner}`).join('\n'):'• 계획 종료일을 초과한 미완료 작업이 없습니다.'}\n\n3. 이번 주 이슈 현황 (${start} ~ ${end})\n신규 ${newIssues.length}건 / 해결 ${resolved.length}건 / 현재 미해결 ${is.filter(i=>i.status!=='해결').length}건\n${is.filter(i=>i.status!=='해결').map(i=>`• [${i.severity} · ${i.status}] ${i.title} · ${i.owner} · ${i.due}까지`).join('\n')||'• 현재 미해결 이슈가 없습니다.'}\n\n4. 이번 주 납품 및 다음 주 계획\n${due.length?due.map(p=>`• 이번 주 납품: ${p.name} · ${p.due}`).join('\n'):'• 이번 주 예정된 납품이 없습니다.'}\n${next.slice(0,8).map(t=>`• 다음 주: ${pName(t.project)} / ${t.name} · ${t.start} ~ ${t.end}`).join('\n')||'• 다음 주 예정 작업이 없습니다.'}\n\n확인 사항: 이 문서는 현재 저장된 데이터의 계산 결과로 작성된 참고용 초안입니다. 지연 원인과 후속 영향은 담당자가 확인해 주세요.`;}
function weeklyPage(){const report=db.reports[reportKey()]||generateReport();return pageHead('WEEKLY BRIEF','주간 현황 요약','이번 주의 진행과 이슈를 정리하고, 다음 주를 준비하세요.',`<button class="btn" data-action="report-print">${icon('print')}인쇄 · PDF</button><button class="btn" data-action="report-export">${icon('download')}엑셀 내보내기</button><button class="btn primary" data-action="report-save">${icon('check')}수정 내용 저장</button>`)+`<div class="report-grid"><section class="panel report-settings"><label>대상 프로젝트<select id="project-select">${projectOptions(project,true)}</select></label><label>보고 주간 시작일<input type="date" id="report-date" value="${reportDate}" required></label><button class="btn primary" data-action="report-generate">${icon('sparkle')}최신 데이터로 초안 만들기</button><div class="report-note">데이터 기반 요약 · AI 미연결<br><br>진행률·지연은 계산으로 정리합니다. 문장을 직접 수정한 뒤 저장하거나 내보낼 수 있습니다.<br><br>작성 주간의 신규·해결 건수와 현재 시점의 진행·지연 현황을 구분합니다.</div></section><article class="report-paper"><div class="eyebrow">CELLINK / PROJECT WEEKLY REPORT</div><h2>한 주의 흐름,<br>다음 공정을 위한 준비.</h2><div class="report-meta">${reportDate} – ${dateAdd(reportDate,6)} &nbsp; | &nbsp; ${project==='all'?'전체 프로젝트':esc(pName(project))} &nbsp; | &nbsp; 작성 ${esc(user.name)}</div><span class="tag good">직접 수정할 수 있는 초안</span><h3>프로젝트 주간 현황</h3><textarea id="report-text" aria-label="주간 보고서 내용">${esc(report)}</textarea></article></div>`;}
function docsPage(){const ds=db.docs.filter(d=>(project==='all'||d.project===project)&&(!filterText||`${d.name} ${d.code} ${d.owner}`.includes(filterText)));return pageHead('DOCUMENT CONTROL',mode==='easy'?'도면 보기':'도면 · 문서','승인된 최신 도면과 문서를 확인하고, 개정 이력을 관리합니다.',mode==='easy'?'':`<button class="btn primary" data-action="new-doc">${icon('upload')}문서 등록</button>`)+`<div class="toolbar">${projectSelect()}<input class="search" id="page-search" placeholder="문서명, 도면 번호 검색" aria-label="문서 검색" value="${esc(filterText)}"></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>문서명 / 번호</th><th>프로젝트</th><th>개정</th><th>상태</th><th>담당자</th><th>수정일</th><th>파일</th></tr></thead><tbody>${ds.map(d=>`<tr><td><button class="link doc-name" data-action="doc-detail" data-id="${esc(d.id)}"><span class="doc-icon">${d.data?'FILE':'DEMO'}</span><span style="text-align:left;color:var(--ink)">${esc(d.name)}<span class="subline">${esc(d.code)} · ${esc(d.type)}</span></span></button></td><td>${esc(pName(d.project))}</td><td class="num">${esc(d.revision)}</td><td>${badge(d.status)}</td><td>${person(d.owner)}</td><td class="num">${shortDate(d.updated)}</td><td><button class="iconbtn" data-action="doc-download" data-id="${esc(d.id)}" aria-label="${esc(d.name)} ${d.data?'다운로드':'샘플 설명 다운로드'}">${icon('download')}</button></td></tr>`).join('')}</tbody></table></div>${!ds.length?empty('등록된 문서가 없습니다.'):''}</section><p class="muted" style="font-size:11px;line-height:1.9;margin-top:16px">DEMO 문서는 문서 관리 체험용 메타데이터입니다. 실제 도면은 포함되지 않으며, 내려받으면 샘플 설명 파일이 생성됩니다.</p>`;}
function bomPage(){const bs=db.bom.filter(b=>(project==='all'||b.project===project)&&(!filterText||`${b.code} ${b.name} ${b.spec}`.includes(filterText)));return pageHead('BILL OF MATERIALS','부품 구성 · BOM','상위 조립체에서 구매 부품까지, 설비를 이루는 구성을 관리합니다.',`<button class="btn" data-action="bom-export">${icon('download')}내보내기</button><button class="btn primary" data-action="new-bom">${icon('plus')}부품 등록</button>`)+`<div class="toolbar">${projectSelect()}<input class="search" id="page-search" aria-label="부품 검색" placeholder="부품 번호, 부품명, 규격 검색" value="${esc(filterText)}"></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>부품 번호 / 부품명</th><th>규격</th><th>프로젝트</th><th>수량</th><th>조달</th><th>개정</th><th>수정</th></tr></thead><tbody>${bs.map(b=>`<tr><td><div style="padding-left:${Number(b.level)*16}px"><span class="bom-level">${b.level?'↳':icon('box')}</span><strong>${esc(b.name)}</strong><span class="subline num">${esc(b.code)} · LEVEL ${b.level}</span></div></td><td>${esc(b.spec)}</td><td>${esc(pName(b.project))}</td><td class="num">${b.qty} ${esc(b.unit)}</td><td>${badge(b.supply)}</td><td class="num">${esc(b.revision)}</td><td><button class="iconbtn" data-action="edit-bom" data-id="${esc(b.id)}" aria-label="${esc(b.name)} 수정">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div>${!bs.length?empty('등록된 부품이 없습니다.'):''}</section>`;}
function changesPage(){const cs=db.changes.filter(c=>project==='all'||c.project===project);return pageHead('ENGINEERING CHANGE','설계 변경 · 승인','변경 사유와 관련 문서를 남기고, 검토 후 반영하세요.',`<button class="btn primary" data-action="new-change">${icon('plus')}변경 요청 등록</button>`)+overviewTools()+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>변경 번호 / 내용</th><th>프로젝트</th><th>요청자</th><th>요청일</th><th>상태</th><th>검토</th></tr></thead><tbody>${cs.map(c=>`<tr><td class="title-cell"><strong>${esc(c.title)}</strong><span class="subline">${esc(c.id)}</span></td><td>${esc(pName(c.project))}</td><td>${person(c.owner)}</td><td class="num">${shortDate(c.created)}</td><td>${badge(c.status)}</td><td><button class="btn sm" data-action="change-detail" data-id="${esc(c.id)}">${c.status==='검토 요청'?'검토하기':'상세 보기'}</button></td></tr>`).join('')}</tbody></table></div>${!cs.length?empty('등록된 설계 변경 요청이 없습니다.'):''}</section><p class="muted" style="font-size:11px;margin-top:16px;line-height:1.8">체험용 승인 흐름입니다. 승인해도 도면 개정이나 일정이 자동 변경되지는 않습니다. 관련 문서와 작업을 검토 후 직접 수정해 주세요.</p>`;}
function easyDashboard(){const my=currentTasks().filter(t=>t.owner===user.name&&t.progress<100&&(t.start<=TODAY||t.progress>0));return pageHead('MY WORKSPACE',`${esc(user.name)}님, 오늘도 안전하게.`,`오늘은 ${shortDate(TODAY)}입니다. 내 작업을 확인하고 진행 상황을 알려주세요.`)+`<div class="easy-welcome"><div><h2>지금 해야 할 일만, 쉽고 크게.</h2><p>아래 작업을 누르면 진행 상황을 바꿀 수 있어요.</p></div><button class="btn primary" data-action="new-issue">${icon('plus')}문제 등록하기</button></div><div class="easy-actions"><button data-nav="schedule">${icon('calendar')}내 작업 일정</button><button data-nav="issues">${icon('issue')}문제 확인</button><button data-nav="docs">${icon('file')}도면 보기</button></div>${overviewTools()}<div class="easy-grid">${my.map(t=>`<article class="panel easy-task">${badge(late(t)?'지연':t.progress>0?'진행 중':'예정')}<h2>${esc(t.name)}</h2><p>${esc(pName(t.project))}<br>${shortDate(t.start)} ~ ${shortDate(t.end)} · ${esc(t.stage)}</p><div style="display:flex;justify-content:space-between;margin-top:22px;font-size:16px"><span>내 작업 진행률</span><strong>${t.progress}%</strong></div><div class="progress-line"><i style="width:${t.progress}%"></i></div><button class="btn primary" data-action="easy-progress" data-id="${esc(t.id)}">${icon('edit')}진행 상황 입력하기</button></article>`).join('')}</div>${!my.length?`<section class="panel">${empty('내 이름으로 배정된 미완료 작업이 없습니다. 담당자 이름이 맞는지 확인해 주세요.','checkcircle')}</section>`:''}`;}
function easySchedule(){const ts=currentTasks().filter(t=>t.owner===user.name);return pageHead('MY SCHEDULE','내 작업 일정','작업을 누르면 진행 상황을 입력할 수 있어요.')+overviewTools()+`<section class="panel">${taskTable(ts)}</section>`;}
function importPage(){return pageHead('DATA IMPORT','엑셀 가져오기','표준 양식으로 일정과 이슈를 모으고, 내용을 확인한 뒤 저장하세요.',`<button class="btn" data-action="template-download">${icon('download')}표준 양식 받기</button>`)+`<section class="panel" style="padding:25px"><div class="toolbar"><label style="flex-direction:row;align-items:center">가져올 자료<select id="import-kind">${options([{value:'tasks',label:'일정 · 작업'},{value:'issues',label:'이슈 목록'},{value:'projects',label:'프로젝트 목록'}],importKind)}</select></label></div><div class="import-panel">${icon('upload')}<h2>흩어진 업무를 한곳으로.</h2><p>엑셀(.xlsx) 또는 CSV 파일을 여러 개 선택할 수 있습니다.<br>먼저 프로젝트를 등록한 뒤 해당 프로젝트 ID로 일정·이슈를 올려주세요.<br>한 번에 파일당 5MB, 전체 1,000행까지 가져올 수 있습니다.</p><label class="btn primary" style="display:inline-flex;flex-direction:row;cursor:pointer">${icon('folder')}파일 선택하기<input type="file" id="import-files" accept=".xlsx,.csv" multiple style="display:none"></label><button class="btn" data-action="template-download">${icon('download')}양식 다운로드</button></div>${importRows?`<div class="import-preview"><div class="import-summary"><strong>${importRows.length}행 미리보기</strong><button class="btn primary" data-action="import-confirm" ${importErrors.length||!importRows.length?'disabled':''}>${icon('check')}확인하고 가져오기</button></div>${importErrors.length?`<div class="report-note red">${importErrors.map(esc).join('<br>')}</div>`:'<p class="report-note">검증을 통과했습니다. 아래 내용을 확인하고 저장하세요. 아직 데이터에 반영되지 않았습니다.</p>'}<div class="table-wrap"><table><thead><tr>${Object.keys(importRows[0]||{}).map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${importRows.slice(0,12).map(r=>`<tr>${Object.values(r).map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${importRows.length>12?'<p class="muted" style="padding:15px">처음 12행만 표시합니다. 저장 시 전체 행이 반영됩니다.</p>':''}</div>`:''}</section><div class="report-note">표준 시트 이름: 프로젝트 / 일정 / 이슈. 필수 열과 예시는 양식에 포함되어 있습니다. 기존 ID와 중복되거나 날짜·진행률·프로젝트 연결이 올바르지 않으면 저장 전 오류를 안내합니다.</div>`;}
function helpPage(){return pageHead('GETTING STARTED','함께 쓰는 쉬운 PLM','처음이라도 괜찮아요. 세 가지만 기억해 주세요.')+`<div class="help-grid"><section class="panel help-card"><div class="step">01</div><h2>전체 흐름부터 확인해요</h2><p>통합 현황에서 진행률, 지연 작업, 미해결 이슈를 확인하세요. 주황색은 확인이 필요한 항목입니다. 글씨 옆 상태를 함께 읽으면 색을 구분하지 않아도 알 수 있어요.</p><button class="btn" data-nav="dashboard">현황 보러 가기 ${icon('arrow')}</button></section><section class="panel help-card"><div class="step">02</div><h2>내 작업을 알려 주세요</h2><p>작업을 누르고 진행률을 바꾼 뒤 저장하세요. 문제가 생기면 이슈를 등록해 담당자와 기한을 남겨요. 쉬운 화면으로 전환하면 큰 글씨와 버튼으로 쓸 수 있어요.</p><button class="btn" data-nav="schedule">일정 보러 가기 ${icon('arrow')}</button></section><section class="panel help-card"><div class="step">03</div><h2>한 주를 정리해요</h2><p>관리용 화면의 주간 현황 요약에서 초안을 만들 수 있어요. 현재 데이터로 정리된 내용은 직접 수정하고 저장하거나 엑셀로 내려받을 수 있어요.</p><button class="btn" data-action="help-weekly">주간 현황 보기 ${icon('arrow')}</button></section></div><section class="panel" style="padding:26px;margin-top:22px"><h2 style="font-size:17px">이 체험 공간에 대해</h2><p class="muted" style="line-height:2;font-size:13px;margin-top:14px">가상 고객과 가상 설비 프로젝트로 구성했습니다. 입력 데이터와 첨부파일은 사용 중인 브라우저에 저장되며 다른 컴퓨터·사용자와 공유되지 않습니다. 배포 사이트 접근에는 ChatGPT 로그인이 적용되며 사내 계정, 서버 저장, 실제 AI 연결, 부서별 권한은 별도 연동이 필요합니다. 현장용·관리용 전환은 화면 편의 설정입니다.</p><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:20px"><button class="btn" data-action="backup">${icon('download')}전체 데이터 백업</button><button class="btn" data-action="restore">${icon('upload')}백업 불러오기</button><button class="btn" data-action="reset">샘플 데이터로 초기화</button></div></section>`;}
function render(){document.body.classList.toggle('easy-mode',Boolean(user)&&mode==='easy');if(!user){$('#app').innerHTML=login();$('#entry-form').onsubmit=e=>{e.preventDefault();const name=new FormData(e.currentTarget).get('name').trim();if(!name)return;user={name,mode:entryMode};mode=entryMode;try{sessionStorage.setItem('cellink-user',JSON.stringify(user));}catch{}render();};return;}
 const pages={dashboard:mode==='easy'?easyDashboard:dashboard,projects:projectsPage,schedule:mode==='easy'?easySchedule:schedulePage,issues:issuesPage,weekly:weeklyPage,docs:docsPage,bom:bomPage,changes:changesPage,import:importPage,help:helpPage};$('#app').innerHTML=frame((pages[view]||dashboard)());
 if(view==='schedule'&&mode!=='easy')mountGantt();
 $('#project-select')?.addEventListener('change',e=>{project=e.target.value;render();});
 $('#page-search')?.addEventListener('input',e=>{filterText=e.target.value;const pos=e.target.selectionStart;render();const n=$('#page-search');n?.focus();n?.setSelectionRange(pos,pos);});
 $('#market-filter')?.addEventListener('change',e=>{projectMarket=e.target.value;render();});
 for(const [sel,key] of [['#issue-status','status'],['#issue-owner','owner'],['#issue-category','category']])$(sel)?.addEventListener('change',e=>{if(key==='status')issueStatus=e.target.value;if(key==='owner')issueOwner=e.target.value;if(key==='category')issueCategory=e.target.value;render();});
 $('#report-date')?.addEventListener('change',e=>{if(!e.target.value)return;reportDate=weekStart(e.target.value);render();});
 $('#import-kind')?.addEventListener('change',e=>{importKind=e.target.value;importRows=null;importErrors=[];render();});
 $('#import-files')?.addEventListener('change',e=>readImport(e.target.files));
 $('#global-search')?.addEventListener('submit',e=>{e.preventDefault();searchAll(new FormData(e.currentTarget).get('q').trim());});
}
function navigate(to){view=to;detailProject=null;filterText='';render();window.scrollTo({top:0,behavior:'instant'});}
function projectForm(id){const p=db.projects.find(x=>x.id===id)||{id:'',name:'',customer:'',equipment:'롤투롤 코터',market:'내수',country:'대한민국',owner:user.name,start:TODAY,due:dateAdd(TODAY,60)};modal(id?'프로젝트 정보 수정':'프로젝트 만들기',`<div class="dialog-form"><label class="full">프로젝트명<input name="name" required maxlength="80" value="${esc(p.name)}" placeholder="예: 전극 코팅 라인 #03"></label><label>고객사<input name="customer" required maxlength="60" value="${esc(p.customer)}" placeholder="예: A사"></label><label>설비 종류<select name="equipment">${options(['롤투롤 코터','롤프레스','슬리터','노칭기','조립·검사 설비','활성화·물류 설비','기타'],p.equipment)}</select></label><label>납품 구분<select name="market">${options(['내수','수출'],p.market)}</select></label><label>납품 국가<input name="country" required maxlength="40" value="${esc(p.country)}"></label><label>시작일<input type="date" name="start" required value="${p.start}"></label><label>납품 예정일<input type="date" name="due" required value="${p.due}"></label><label class="full">프로젝트 담당자<input name="owner" required maxlength="30" value="${esc(p.owner)}"></label></div>`,formButtons(),fd=>{const v=Object.fromEntries(fd);if(v.due<v.start){toast('납품 예정일은 시작일 이후로 선택해 주세요.');return;}if(!v.name.trim()||!v.owner.trim()){toast('프로젝트명과 담당자를 입력해 주세요.');return;}const item={...p,...v,id:p.id||uid('P')};if(commit(()=>{if(id)db.projects[db.projects.findIndex(x=>x.id===id)]=item;else db.projects.push(item);log(`${item.name} 프로젝트가 ${id?'수정':'등록'}되었습니다.`,'folder');},'프로젝트를 저장했습니다.'))closeModal();});}
function taskForm(id,pid){const t=db.tasks.find(x=>x.id===id)||{id:'',project:pid||((project!=='all'?project:null)||db.projects[0]?.id),name:'',stage:'조립',owner:user.name,start:TODAY,end:dateAdd(TODAY,7),progress:0,predecessor:''};if(!db.projects.length){toast('먼저 프로젝트를 등록해 주세요.');return;}if(mode==='easy'&&id){easyProgress(id);return;}
 modal(id?'작업 일정 · 진행 수정':'작업 등록',`<div class="dialog-form"><label class="full">프로젝트<select name="project" id="task-project">${projectOptions(t.project)}</select></label><label class="full">작업명<input name="name" required maxlength="100" value="${esc(t.name)}" placeholder="예: 언와인더 기계 조립"></label><label>공정<select name="stage">${options(['설계','구매','가공','조립','시운전','검수·출하','현장 설치·SAT','유지보수'],t.stage)}</select></label><label>담당자<input name="owner" required maxlength="30" value="${esc(t.owner)}"></label><label>계획 시작일<input type="date" name="start" required value="${t.start}"></label><label>계획 종료일<input type="date" name="end" required value="${t.end}"></label><label>진행률 (%)<input type="number" name="progress" min="0" max="100" step="1" required value="${t.progress}"></label><label>선행 작업<select name="predecessor" id="task-predecessor"><option value="">선행 작업 없음</option>${options(db.tasks.filter(x=>x.project===t.project&&x.id!==t.id).map(x=>({value:x.id,label:x.name})),t.predecessor)}</select></label></div><p class="hint">계획 종료일을 지났고 진행률이 100% 미만이면 지연으로 표시합니다. 선행 작업은 연결 표시용이며 후속 일정은 자동 변경하지 않습니다.</p>`,formButtons(),fd=>{const v=Object.fromEntries(fd);if(v.end<v.start){toast('종료일은 시작일 이후로 선택해 주세요.');return;}if(!v.name.trim()||!v.owner.trim()){toast('작업명과 담당자를 입력해 주세요.');return;}const seen=new Set([id]);let parent=v.predecessor;while(parent){if(seen.has(parent)){toast('선행 작업이 서로 순환하지 않도록 선택해 주세요.');return;}seen.add(parent);parent=db.tasks.find(x=>x.id===parent)?.predecessor||'';}const item={...t,...v,progress:Number(v.progress),id:t.id||uid('T')};if(commit(()=>{if(id)db.tasks[db.tasks.findIndex(x=>x.id===id)]=item;else db.tasks.push(item);log(`${item.name} 작업이 ${id?'수정':'등록'}되었습니다.`,'chart');},'작업을 저장했습니다.'))closeModal();});
 $('#task-project').onchange=e=>{$('#task-predecessor').innerHTML='<option value="">선행 작업 없음</option>'+options(db.tasks.filter(x=>x.project===e.target.value&&x.id!==t.id).map(x=>({value:x.id,label:x.name})));};
}
function easyProgress(id){const t=db.tasks.find(t=>t.id===id);if(!t)return;modal('진행 상황 입력하기',`<p class="muted">${esc(pName(t.project))}</p><h3 style="font-size:23px;line-height:1.7;margin:14px 0 22px">${esc(t.name)}</h3><label style="font-size:17px">얼마나 진행했나요?<select name="progress" style="font-size:20px;padding:17px">${options([...new Set([0,25,50,75,100,Number(t.progress)])].sort((a,b)=>a-b).map(v=>({value:v,label:v===0?'시작 전 · 0%':v===100?'모두 마쳤어요 · 100%':`${v}% 진행했어요`})),t.progress)}</select></label><p class="hint">저장하면 일정과 현황 화면에도 함께 반영됩니다.</p>`,formButtons('진행 상황 저장'),fd=>{if(commit(()=>{t.progress=Number(fd.get('progress'));log(`${t.name} 진행률이 ${t.progress}%로 변경되었습니다.`,'checkcircle');},'진행 상황을 저장했어요.'))closeModal();});}
function issueForm(id,defaults={}){const i=db.issues.find(x=>x.id===id)||{id:'',project:(project!=='all'?project:null)||db.projects[0]?.id,title:'',description:'',category:'기타',severity:'보통',status:'접수',owner:user.name,due:dateAdd(TODAY,3),created:TODAY,task:'',...defaults};if(!db.projects.length){toast('먼저 프로젝트를 등록해 주세요.');return;}
 const easy=mode==='easy';modal(id?'이슈 수정':easy?'문제 등록하기':'이슈 등록',`<div class="dialog-form"><label class="full">어느 프로젝트인가요?<select name="project" id="issue-project">${projectOptions(i.project)}</select></label><label class="full">${easy?'어떤 문제가 있나요?':'이슈 제목'}<input name="title" required maxlength="140" value="${esc(i.title)}" placeholder="예: 감속기 입고가 늦어지고 있어요"></label><label class="full">자세한 내용<textarea name="description" maxlength="4000" placeholder="현재 상황과 필요한 조치를 적어주세요.">${esc(i.description)}</textarea></label><label>담당자<input name="owner" required maxlength="30" value="${esc(i.owner)}"></label><label>언제까지 확인할까요?<input type="date" name="due" required value="${i.due}"></label><label>중요도<select name="severity">${options(['낮음','보통','높음'],i.severity)}</select></label><label>상태<select name="status">${options(['접수','조치 중','해결'],i.status)}</select></label>${easy?`<input type="hidden" name="category" value="${esc(i.category)}"><input type="hidden" name="task" value="${esc(i.task)}">`:`<label>분류<select name="category">${options(['품질','납기','사양','안전','기타'],i.category)}</select></label><label>관련 작업<select name="task" id="issue-task"><option value="">연결하지 않음</option>${options(db.tasks.filter(t=>t.project===i.project).map(t=>({value:t.id,label:t.name})),i.task)}</select></label>`}</div>${defaults.extracted?'<p class="hint">규칙 기반으로 추출한 초안입니다. 내용·담당자·기한을 직접 확인하고 저장하세요.</p>':''}`,formButtons(id?'수정 내용 저장':easy?'문제 등록하기':'확인 후 등록'),fd=>{const v=Object.fromEntries(fd);if(!v.title.trim()||!v.owner.trim()){toast('제목과 담당자를 입력해 주세요.');return;}const item={...i,...v,id:i.id||uid('ISS')};if(v.status==='해결'&&i.status!=='해결')item.resolved=TODAY;if(v.status!=='해결')delete item.resolved;delete item.extracted;if(item.task&&!db.tasks.some(t=>t.id===item.task&&t.project===item.project))item.task='';if(commit(()=>{if(id)db.issues[db.issues.findIndex(x=>x.id===id)]=item;else db.issues.push(item);log(`${item.title} 이슈가 ${id?'수정':'등록'}되었습니다.`,'issue');},'이슈를 저장했습니다.'))closeModal();});
 $('#issue-project').onchange=e=>{const sel=$('#issue-task');if(sel)sel.innerHTML='<option value="">연결하지 않음</option>'+options(db.tasks.filter(t=>t.project===e.target.value).map(t=>({value:t.id,label:t.name})));};
}
function issueDetail(id){const i=db.issues.find(x=>x.id===id);if(!i)return;const t=db.tasks.find(t=>t.id===i.task);modal('이슈 상세',`${badge(i.severity)} ${badge(i.category)} ${badge(i.status)}<h3 style="font-size:22px;line-height:1.7;margin:18px 0">${esc(i.title)}</h3><div class="detail-dl"><div><small>프로젝트</small><strong>${esc(pName(i.project))}</strong></div><div><small>담당자</small>${person(i.owner)}</div><div><small>조치 기한</small><strong>${i.due}</strong></div><div><small>등록일</small><strong>${i.created}</strong></div></div><div class="detail-section"><strong>상황 및 조치 내용</strong><p>${esc(i.description||'상세 내용이 없습니다.')}</p></div>${t?`<div class="detail-section"><strong>관련 작업</strong><button type="button" class="link" data-action="edit-task" data-id="${esc(t.id)}">${esc(t.name)} · ${t.progress}% ${icon('arrow')}</button></div>`:''}`,`<button class="btn" type="button" data-action="edit-issue" data-id="${esc(i.id)}">${icon('edit')}내용 수정</button>${i.status!=='해결'?`<button type="button" class="btn primary" data-action="issue-next" data-id="${esc(i.id)}">${icon('check')}${i.status==='접수'?'조치 시작':'해결 완료'}</button>`:'<button class="btn primary" type="button" data-action="close">확인</button>'}`);}
function extractForm(){modal('메모에서 이슈 추출',`<label>메일 · 회의 메모를 붙여 넣으세요<textarea name="memo" required minlength="5" maxlength="4000" style="min-height:180px" placeholder="예: 감속기 납기가 지연되었습니다. 담당: 박지훈, 기한: 2026-11-06. 조립 일정을 확인해 주세요."></textarea></label><div class="report-note">규칙 기반 체험 기능 · AI 미연결<br>품질·납기·사양 키워드, ‘담당: 이름’, ‘기한: YYYY-MM-DD’를 찾아 입력 초안을 만듭니다. 저장 전 확인할 수 있습니다.</div>`,formButtons('내용 추출하기'),fd=>{const text=String(fd.get('memo')).trim();const category=/지연|납기|입고/.test(text)?'납기':/불량|품질|치수|조도|검사/.test(text)?'품질':/사양|변경|요청/.test(text)?'사양':/안전|사고/.test(text)?'안전':'기타';const due=text.match(/기한\s*[:：]\s*(\d{4}-\d{2}-\d{2})/)?.[1];const owner=text.match(/담당\s*[:：]\s*([^,，\n. ]+)/)?.[1];issueForm(null,{title:text.split(/[\n.]/)[0].slice(0,100),description:text,category,severity:/긴급|중대|안전|사고/.test(text)?'높음':'보통',due:validDate(due)?due:dateAdd(TODAY,3),owner:owner||user.name,extracted:true});});}
function docForm(id){const d=db.docs.find(x=>x.id===id)||{id:'',project:project!=='all'?project:db.projects[0]?.id,name:'',code:'',revision:'Rev.A',type:'도면',status:'검토 중',owner:user.name};modal(id?'문서 개정 · 정보 수정':'문서 등록',`<div class="dialog-form"><label class="full">프로젝트<select name="project">${projectOptions(d.project)}</select></label><label class="full">문서명<input name="name" required maxlength="100" value="${esc(d.name)}"></label><label>도면 · 문서 번호<input name="code" required maxlength="60" value="${esc(d.code)}"></label><label>개정 번호<input name="revision" required maxlength="20" value="${esc(d.revision)}" placeholder="Rev.A"></label><label>문서 종류<select name="type">${options(['도면','사양서','검사성적서','매뉴얼','수출 서류','기타'],d.type)}</select></label><label>상태<select name="status">${options(['검토 중','승인','폐기'],d.status)}</select></label><label class="full">담당자<input name="owner" required maxlength="30" value="${esc(d.owner)}"></label><label class="full">파일 첨부 (최대 1MB)<input name="file" type="file" accept=".pdf,.png,.jpg,.jpeg,.txt,.csv,.xlsx,.dwg,.dxf,.step,.stp"><small>브라우저 저장 공간을 사용합니다.${id?' 새 파일을 선택하면 기존 파일을 대체합니다.':''}</small></label></div>`,formButtons(),async fd=>{const file=fd.get('file');if(file?.size>1048576){toast('첨부파일은 1MB 이하로 선택해 주세요.');return;}const v=Object.fromEntries([...fd].filter(([k])=>k!=='file'));const item={...d,...v,id:d.id||uid('D'),updated:TODAY};if(file?.size){try{item.data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file);});item.filename=file.name;}catch{toast('첨부파일을 읽지 못했습니다. 다시 선택해 주세요.');return;}}if(commit(()=>{if(id){if(d.revision!==item.revision){item.history=[...(d.history||[]),{revision:d.revision,updated:d.updated,name:d.name}];}db.docs[db.docs.findIndex(x=>x.id===id)]=item;}else db.docs.push(item);log(`${item.name} 문서가 ${id?'수정':'등록'}되었습니다.`,'file');},'문서를 저장했습니다.'))closeModal();});}
function docDetail(id){const d=db.docs.find(x=>x.id===id);if(!d)return;modal('문서 상세',`${badge(d.status)}<h3 style="font-size:23px;margin:16px 0">${esc(d.name)}</h3><div class="detail-dl"><div><small>문서 번호</small><strong>${esc(d.code)}</strong></div><div><small>최신 개정</small><strong>${esc(d.revision)}</strong></div><div><small>프로젝트</small><strong>${esc(pName(d.project))}</strong></div><div><small>담당자</small><strong>${esc(d.owner)}</strong></div></div><div class="detail-section"><strong>개정 이력</strong><p>${esc(d.revision)} · ${d.updated} · 현재 개정${(d.history||[]).slice().reverse().map(h=>`<br>${esc(h.revision)} · ${esc(h.updated)} · 이전 개정`).join('')}</p></div><p class="hint">${d.data?'첨부파일: '+esc(d.filename):'샘플 메타데이터입니다. 실제 도면은 포함되지 않습니다.'}</p>`,`<button type="button" class="btn" data-action="doc-download" data-id="${esc(id)}">${icon('download')}${d.data?'파일 다운로드':'샘플 설명 받기'}</button>${mode!=='easy'?`<button type="button" class="btn primary" data-action="edit-doc" data-id="${esc(id)}">${icon('edit')}개정 · 정보 수정</button>`:''}`);}
function bomForm(id){const b=db.bom.find(x=>x.id===id)||{id:'',project:project!=='all'?project:db.projects[0]?.id,code:'',name:'',spec:'',qty:1,unit:'EA',level:1,supply:'구매',revision:'A'};modal(id?'부품 정보 수정':'부품 등록',`<div class="dialog-form"><label class="full">프로젝트<select name="project">${projectOptions(b.project)}</select></label><label>부품 번호<input name="code" required maxlength="60" value="${esc(b.code)}"></label><label>부품명<input name="name" required maxlength="100" value="${esc(b.name)}"></label><label class="full">규격<input name="spec" maxlength="150" value="${esc(b.spec)}"></label><label>수량<input type="number" name="qty" required min="0.001" max="1000000" step="any" value="${b.qty}"></label><label>단위<select name="unit">${options(['EA','SET','M','KG'],b.unit)}</select></label><label>구성 단계 (0: 최상위)<input type="number" name="level" required min="0" max="5" value="${b.level}"></label><label>조달 구분<select name="supply">${options(['구매','제작'],b.supply)}</select></label><label>개정<input name="revision" required maxlength="20" value="${esc(b.revision)}"></label></div>`,formButtons(),fd=>{const v=Object.fromEntries(fd);if(db.bom.some(x=>x.id!==id&&x.project===v.project&&x.code===v.code)){toast('같은 프로젝트에 동일한 부품 번호가 있습니다.');return;}const item={...b,...v,id:b.id||uid('B'),qty:Number(v.qty),level:Number(v.level)};if(commit(()=>{if(id)db.bom[db.bom.findIndex(x=>x.id===id)]=item;else db.bom.push(item);log(`${item.name} 부품 구성이 저장되었습니다.`,'box');},'부품 정보를 저장했습니다.'))closeModal();});}
function changeForm(){modal('설계 변경 요청',`<div class="dialog-form"><label class="full">프로젝트<select name="project" id="change-project">${projectOptions(project!=='all'?project:db.projects[0]?.id)}</select></label><label class="full">변경 제목<input name="title" required maxlength="120" placeholder="예: 코팅 헤드 브래킷 형상 변경"></label><label class="full">변경 사유 · 영향<textarea name="reason" required maxlength="4000" placeholder="변경 이유와 도면·부품·일정에 미치는 영향을 적어주세요."></textarea></label><label>요청자<input name="owner" required maxlength="30" value="${esc(user.name)}"></label><label>관련 문서<select name="document" id="change-document"><option value="">연결하지 않음</option>${options(db.docs.filter(d=>d.project===(project!=='all'?project:db.projects[0]?.id)).map(d=>({value:d.id,label:d.name})))}</select></label></div><p class="hint">등록하면 ‘검토 요청’ 상태로 저장됩니다. 승인 결과와 검토 의견은 이력으로 남습니다.</p>`,formButtons('검토 요청 등록'),fd=>{const v=Object.fromEntries(fd);if(commit(()=>{db.changes.push({...v,id:uid('ECN'),status:'검토 요청',created:TODAY,reviewer:''});log(`${v.title} 설계 변경 검토가 요청되었습니다.`,'change');},'변경 검토 요청을 등록했습니다.'))closeModal();});$('#change-project').onchange=e=>{$('#change-document').innerHTML='<option value="">연결하지 않음</option>'+options(db.docs.filter(d=>d.project===e.target.value).map(d=>({value:d.id,label:d.name})));};}
function changeDetail(id){const c=db.changes.find(x=>x.id===id);if(!c)return;modal('설계 변경 검토',`${badge(c.status)}<h3 style="font-size:22px;line-height:1.7;margin:15px 0">${esc(c.title)}</h3><div class="detail-dl"><div><small>프로젝트</small><strong>${esc(pName(c.project))}</strong></div><div><small>요청자</small><strong>${esc(c.owner)}</strong></div></div><div class="detail-section"><strong>변경 사유 및 영향</strong><p>${esc(c.reason)}</p></div>${c.document?`<div class="detail-section"><strong>관련 문서</strong><button type="button" class="link" data-action="doc-detail" data-id="${esc(c.document)}">${esc(db.docs.find(d=>d.id===c.document)?.name||c.document)} ${icon('arrow')}</button></div>`:''}${c.status==='검토 요청'?'<label style="margin-top:20px">검토 의견<textarea name="review" required maxlength="2000" placeholder="승인 또는 반려 사유를 입력해 주세요."></textarea></label>':`<div class="detail-section"><strong>검토 결과</strong><p>${esc(c.review||'샘플 승인 이력')}<br>검토자: ${esc(c.reviewer)}${c.reviewed?' · '+c.reviewed:''}</p></div>`}`,c.status==='검토 요청'?`<button class="btn" type="submit" id="change-reject">반려</button><button class="btn primary" type="submit" id="change-approve">${icon('check')}승인</button>`:'<button class="btn primary" type="button" data-action="close">확인</button>',(fd)=>{const submitter=$('#modal-form')._submitter;const status=submitter==='change-approve'?'승인':'반려';if(commit(()=>{c.status=status;c.review=String(fd.get('review'));c.reviewer=user.name;c.reviewed=TODAY;log(`${c.title} 설계 변경이 ${status}되었습니다.`,'change');},`설계 변경을 ${status}했습니다.`))closeModal();});$('#modal-form').addEventListener('click',e=>{if(e.target.closest('button[type="submit"]'))$('#modal-form')._submitter=e.target.closest('button').id;});}
function download(name,blob){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function textDownload(name,text){download(name,new Blob(['\ufeff',text],{type:'text/plain;charset=utf-8'}));}
function sheetExport(name,sheets){if(typeof XLSX==='undefined'){toast('엑셀 모듈을 불러오지 못했습니다. 새로고침해 주세요.');return;}const book=XLSX.utils.book_new();for(const [title,rows] of Object.entries(sheets)){const sheet=XLSX.utils.json_to_sheet(rows);sheet['!cols']=Array.from({length:Object.keys(rows[0]||{}).length},()=>({wch:24}));XLSX.utils.book_append_sheet(book,sheet,title);}XLSX.writeFile(book,name);}
function reportExport(){const text=$('#report-text')?.value||generateReport();sheetExport(`주간현황_${reportDate}.xlsx`,{'주간현황':text.split('\n').map(x=>({'보고 내용':x})),'프로젝트':currentProjects().map(p=>({'프로젝트ID':p.id,'프로젝트명':p.name,'진행률':percent(p.id),'납품예정일':p.due})),'이슈':currentIssues().map(i=>({'이슈ID':i.id,'내용':i.title,'담당자':i.owner,'상태':i.status,'기한':i.due}))});}
const importMap={projects:{id:'프로젝트ID',name:'프로젝트명',customer:'고객사',equipment:'설비종류',market:'납품구분',country:'납품국가',owner:'담당자',start:'시작일',due:'납품예정일'},tasks:{id:'작업ID',project:'프로젝트ID',name:'작업명',stage:'공정',owner:'담당자',start:'시작일',end:'종료일',progress:'진행률',predecessor:'선행작업ID'},issues:{id:'이슈ID',project:'프로젝트ID',title:'제목',description:'내용',category:'분류',severity:'중요도',status:'상태',owner:'담당자',due:'기한',created:'등록일',task:'관련작업ID'}};
function templateDownload(){sheetExport('CELLINK_표준입력양식.xlsx',{'프로젝트':[{'프로젝트ID':'P-NEW-001','프로젝트명':'신규 코팅 라인','고객사':'가상 A사','설비종류':'롤투롤 코터','납품구분':'내수','납품국가':'대한민국','담당자':'김민수','시작일':TODAY,'납품예정일':dateAdd(TODAY,60)}],'일정':[{'작업ID':'T-NEW-001','프로젝트ID':'P-NEW-001','작업명':'코팅 헤드 설계','공정':'설계','담당자':'김민수','시작일':TODAY,'종료일':dateAdd(TODAY,7),'진행률':0,'선행작업ID':''}],'이슈':[{'이슈ID':'ISS-NEW-001','프로젝트ID':'P-NEW-001','제목':'고객 전원 사양 확인','내용':'설치 현장 사양 확인 필요','분류':'사양','중요도':'보통','상태':'접수','담당자':'김민수','기한':dateAdd(TODAY,3),'등록일':TODAY,'관련작업ID':'T-NEW-001'}],'사용안내':[{'항목':'가져오기 순서','설명':'프로젝트 → 일정 → 이슈 순서로 같은 파일을 가져오세요. 화면에서 자료 종류를 바꾸면 해당 시트를 읽습니다.'},{'항목':'날짜','설명':'YYYY-MM-DD 또는 엑셀 날짜 셀을 사용하세요.'},{'항목':'필수 값','설명':'ID, 프로젝트ID, 이름/제목, 담당자, 날짜는 필수입니다. 진행률은 0~100입니다.'},{'항목':'중복','설명':'기존 ID는 수정하지 않습니다. 새 ID를 사용하세요.'}]});}
function validDate(v){if(!/^\d{4}-\d{2}-\d{2}$/.test(v||''))return false;const d=new Date(v+'T12:00:00');return !isNaN(d)&&dateISO(d)===v;}
function importDate(v){if(typeof v==='number'){const d=XLSX.SSF.parse_date_code(v);return d?`${d.y}-${String(d.m).padStart(2,'0')}-${String(d.d).padStart(2,'0')}`:'';}return String(v??'').trim();}
async function readImport(files){if(!files.length)return;if(typeof XLSX==='undefined'){toast('엑셀 모듈을 불러오지 못했습니다. 새로고침해 주세요.');return;}importRows=[];importErrors=[];const kind=importKind;const sheetName={projects:'프로젝트',tasks:'일정',issues:'이슈'}[kind];try{for(const f of files){if(f.size>5*1024*1024)throw Error(f.name+': 파일은 5MB 이하로 선택해 주세요.');const w=XLSX.read(await f.arrayBuffer(),{type:'array'});const chosen=w.Sheets[sheetName]||(w.SheetNames.length===1?w.Sheets[w.SheetNames[0]]:null);if(!chosen)throw Error(`${f.name}: '${sheetName}' 시트를 찾을 수 없습니다.`);const rows=XLSX.utils.sheet_to_json(chosen,{defval:''});importRows.push(...rows);if(importRows.length>1000)throw Error('전체 1,000행 이하로 나누어 가져와 주세요.');}validateImport(kind);}catch(err){importErrors.push(err.message);if(importRows.length>1000)importRows=importRows.slice(0,1000);}render();}
function normalizeImport(row,kind){const out={};for(const [key,header]of Object.entries(importMap[kind]))out[key]=['start','end','due','created'].includes(key)?importDate(row[header]):String(row[header]??'').trim();if(kind==='tasks')out.progress=Number(out.progress);if(kind==='issues'){out.created||=TODAY;out.description||='';out.category||='기타';out.severity||='보통';out.status||='접수';if(out.status==='해결')out.resolved=TODAY;}return out;}
function validateImport(kind){const seen=new Set(db[kind].map(x=>x.id));const pendingIds=new Set(importRows.map(r=>String(r[importMap[kind].id]||'').trim()));const errors=[];importRows.forEach((row,idx)=>{const v=normalizeImport(row,kind),no=idx+2;const need=kind==='projects'?['id','name','customer','owner','start','due']:kind==='tasks'?['id','project','name','stage','owner','start','end']:['id','project','title','owner','due'];for(const k of need)if(!v[k])errors.push(`${no}행: ${importMap[kind][k]} 값이 필요합니다.`);if(seen.has(v.id))errors.push(`${no}행: ID '${v.id}'가 중복됩니다.`);seen.add(v.id);if(kind!=='projects'&&!db.projects.some(p=>p.id===v.project))errors.push(`${no}행: 프로젝트 '${v.project}'를 먼저 등록해 주세요.`);for(const k of kind==='projects'?['start','due']:kind==='tasks'?['start','end']:['due','created'])if(!validDate(v[k]))errors.push(`${no}행: ${importMap[kind][k]}는 YYYY-MM-DD 형식의 실제 날짜여야 합니다.`);if((kind==='projects'&&v.due<v.start)||(kind==='tasks'&&v.end<v.start))errors.push(`${no}행: 종료일이 시작일보다 빠릅니다.`);if(kind==='projects'&&!['내수','수출'].includes(v.market))errors.push(`${no}행: 납품구분은 내수 또는 수출이어야 합니다.`);if(kind==='tasks'&&(!Number.isFinite(v.progress)||v.progress<0||v.progress>100||String(row['진행률']).trim()===''))errors.push(`${no}행: 진행률은 0~100 숫자여야 합니다.`);if(kind==='tasks'&&v.predecessor&&!pendingIds.has(v.predecessor)&&!db.tasks.some(t=>t.id===v.predecessor&&t.project===v.project))errors.push(`${no}행: 선행 작업을 찾을 수 없습니다.`);if(kind==='issues'&&(!['접수','조치 중','해결'].includes(v.status)||!['낮음','보통','높음'].includes(v.severity)||!['품질','납기','사양','안전','기타'].includes(v.category)))errors.push(`${no}행: 상태, 중요도 또는 분류가 표준 값과 다릅니다.`);if(kind==='issues'&&v.task&&!db.tasks.some(t=>t.id===v.task&&t.project===v.project))errors.push(`${no}행: 관련 작업이 해당 프로젝트에 없습니다.`);});
 if(kind==='tasks'){const pending=importRows.map(r=>normalizeImport(r,kind));const all=[...db.tasks,...pending];for(const t of pending){const seenChain=new Set([t.id]);let parent=t.predecessor;while(parent){const p=all.find(x=>x.id===parent);if(seenChain.has(parent)){errors.push(`${t.id}: 선행 작업이 순환합니다.`);break;}if(p&&p.project!==t.project){errors.push(`${t.id}: 다른 프로젝트의 선행 작업은 연결할 수 없습니다.`);break;}seenChain.add(parent);parent=p?.predecessor||'';}}}
 importErrors=errors.slice(0,30);if(errors.length>30)importErrors.push(`외 ${errors.length-30}개 오류가 있습니다.`);if(!importRows.length)importErrors.push('읽을 데이터 행이 없습니다.');}
function searchAll(q){if(!q)return;const ps=db.projects.filter(p=>`${p.name} ${p.customer} ${p.owner} ${p.id}`.includes(q)),is=db.issues.filter(i=>`${i.title} ${i.description} ${i.owner}`.includes(q));modal('전체 검색 결과',`<p class="muted">‘${esc(q)}’ 검색 결과</p><div class="detail-section"><strong>프로젝트 ${ps.length}개</strong>${ps.map(p=>`<p style="margin:10px 0"><button type="button" class="link" data-action="search-project" data-id="${esc(p.id)}">${esc(p.name)} ${icon('arrow')}</button></p>`).join('')||'<p>검색 결과가 없습니다.</p>'}</div><div class="detail-section"><strong>이슈 ${is.length}개</strong>${is.map(i=>`<p style="margin:10px 0"><button type="button" class="link" data-action="issue-detail" data-id="${esc(i.id)}">${esc(i.title)} ${icon('arrow')}</button></p>`).join('')||'<p>검색 결과가 없습니다.</p>'}</div>`);}
function switchMode(next){mode=next|| (mode==='easy'?'manager':'easy');user.mode=mode;try{sessionStorage.setItem('cellink-user',JSON.stringify(user));}catch{}view='dashboard';detailProject=null;render();window.scrollTo({top:0,behavior:'instant'});toast(mode==='easy'?'현장용 쉬운 화면으로 바꿨어요.':'관리용 상세 화면으로 바꿨습니다.');}
const actions={
 close:closeModal,'entry-mode':el=>{entryMode=el.dataset.mode;const val=$('#entry-form input').value;render();$('#entry-form input').value=val;},
 'switch-mode':()=>switchMode(),menu:()=>$('.sidebar').classList.toggle('open'),
 logout:()=>{user=null;try{sessionStorage.removeItem('cellink-user');}catch{}view='dashboard';project='all';render();},
 'new-project':()=>projectForm(),'edit-project':el=>projectForm(el.dataset.id),'projects-back':()=>{detailProject=null;render();},
 'project-go':el=>{project=el.dataset.id;navigate(el.dataset.page);},'search-project':el=>{closeModal();view='projects';detailProject=el.dataset.id;render();},
 'new-task':el=>taskForm(null,el.dataset.project),'edit-task':el=>taskForm(el.dataset.id),'easy-progress':el=>easyProgress(el.dataset.id),
 'new-issue':()=>issueForm(),'edit-issue':el=>issueForm(el.dataset.id),'issue-detail':el=>issueDetail(el.dataset.id),
 'issue-next':el=>{const i=db.issues.find(i=>i.id===el.dataset.id);if(!i)return;if(commit(()=>{i.status=i.status==='접수'?'조치 중':'해결';if(i.status==='해결')i.resolved=TODAY;log(`${i.title} 이슈 상태가 ${i.status}로 변경되었습니다.`,'checkcircle');},'이슈 상태를 변경했습니다.'))issueDetail(i.id);},
 extract:extractForm,'issue-layout':el=>{issueLayout=el.dataset.value;render();},'gantt-view':el=>{ganttView=el.dataset.value;render();},
 'report-save':()=>{const val=$('#report-text').value;commit(()=>{db.reports[reportKey()]=val;log('주간 현황 보고서가 저장되었습니다.','report');},'수정한 보고서를 저장했습니다.');},
 'report-generate':()=>{const fresh=generateReport();const existing=$('#report-text').value;if(existing!==fresh){modal('최신 데이터로 다시 만들까요?','<p style="line-height:1.9">지금 편집한 보고서 내용을 현재 저장된 데이터의 초안으로 바꿉니다.</p>',formButtons('초안 다시 만들기'),()=>{if(commit(()=>{db.reports[reportKey()]=fresh;},'최신 데이터로 초안을 만들었습니다.'))closeModal();});}else toast('현재 데이터가 이미 반영된 초안입니다.');},
 'report-export':reportExport,'report-print':()=>{const text=$('#report-text');text.style.height=text.scrollHeight+'px';window.print();},
 'new-doc':()=>docForm(),'edit-doc':el=>docForm(el.dataset.id),'doc-detail':el=>docDetail(el.dataset.id),
 'doc-download':el=>{const d=db.docs.find(x=>x.id===el.dataset.id);if(!d)return;if(d.data){const a=document.createElement('a');a.href=d.data;a.download=d.filename||'문서';a.click();}else textDownload(d.filename||'샘플문서_설명.txt',`CELLINK PLM 체험용 문서 메타데이터\n\n문서명: ${d.name}\n문서번호: ${d.code}\n개정: ${d.revision}\n프로젝트: ${pName(d.project)}\n상태: ${d.status}\n\n이 파일은 샘플 설명입니다. 실제 도면이나 설비 사양은 포함하지 않습니다.`);},
 'new-bom':()=>bomForm(),'edit-bom':el=>bomForm(el.dataset.id),'new-change':changeForm,'change-detail':el=>changeDetail(el.dataset.id),
 'template-download':templateDownload,'import-confirm':()=>{if(!importRows||importErrors.length)return;validateImport(importKind);if(importErrors.length){render();return;}const rows=importRows.map(r=>normalizeImport(r,importKind));if(commit(()=>{db[importKind].push(...rows);log(`엑셀에서 ${rows.length}개 항목을 가져왔습니다.`,'upload');},`${rows.length}개 항목을 가져왔습니다.`)){importRows=null;render();}},
 'schedule-export':()=>sheetExport('CELLINK_일정.xlsx',{'일정':currentTasks().map(t=>Object.fromEntries(Object.entries(importMap.tasks).map(([k,h])=>[h,t[k]])))}),
 'bom-export':()=>sheetExport('CELLINK_BOM.xlsx',{'부품구성':db.bom.filter(b=>project==='all'||b.project===project).map(b=>({'프로젝트':pName(b.project),'부품번호':b.code,'부품명':b.name,'규격':b.spec,'수량':b.qty,'단위':b.unit,'단계':b.level,'조달':b.supply,'개정':b.revision}))}),
 notifications:()=>{const lateTasks=db.tasks.filter(late);const high=db.issues.filter(i=>i.severity==='높음'&&i.status!=='해결');modal('확인이 필요한 업무',`<div class="detail-section"><strong>지연 작업 ${lateTasks.length}건</strong>${lateTasks.map(t=>`<p style="margin:10px 0"><button type="button" class="link" data-action="edit-task" data-id="${esc(t.id)}">${esc(t.name)} · ${lateDays(t)}일 지연 ${icon('arrow')}</button></p>`).join('')||'<p>지연 작업이 없습니다.</p>'}</div><div class="detail-section"><strong>높은 중요도 이슈 ${high.length}건</strong>${high.map(i=>`<p style="margin:10px 0"><button type="button" class="link" data-action="issue-detail" data-id="${esc(i.id)}">${esc(i.title)} ${icon('arrow')}</button></p>`).join('')||'<p>우선 확인 이슈가 없습니다.</p>'}</div>`);},
 'help-weekly':()=>{if(mode==='easy')switchMode('manager');navigate('weekly');},
 backup:()=>{download(`CELLINK_백업_${TODAY}.json`,new Blob([JSON.stringify({version:1,data:db},null,2)],{type:'application/json'}));toast('전체 데이터를 백업했습니다.');},
 restore:()=>{const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{const f=input.files[0];if(!f)return;if(f.size>10*1024*1024)throw Error('백업 파일은 10MB 이하로 선택해 주세요.');const v=JSON.parse(await f.text());if(v.version!==1||!v.data||!['projects','tasks','issues','docs','bom','changes','logs'].every(k=>Array.isArray(v.data[k]))||typeof v.data.reports!=='object')throw Error('CELLINK 백업 형식이 아닙니다.');for(const key of ['projects','tasks','issues','docs','bom','changes']){const ids=new Set();for(const r of v.data[key]){if(!r||typeof r.id!=='string'||ids.has(r.id))throw Error('백업의 항목 ID를 확인해 주세요.');ids.add(r.id);}}for(const t of v.data.tasks)if(!validDate(t.start)||!validDate(t.end)||t.end<t.start||!Number.isFinite(Number(t.progress))||t.progress<0||t.progress>100||!v.data.projects.some(p=>p.id===t.project))throw Error('백업의 작업 날짜와 연결을 확인해 주세요.');for(const i of v.data.issues)if(!validDate(i.due)||!v.data.projects.some(p=>p.id===i.project))throw Error('백업의 이슈 날짜와 연결을 확인해 주세요.');modal('백업을 불러올까요?',`<p style="line-height:1.9">현재 브라우저의 데이터를 백업 파일 내용으로 바꿉니다. 프로젝트 ${v.data.projects.length}개, 작업 ${v.data.tasks.length}개가 포함되어 있습니다.</p>`,formButtons('백업 불러오기'),()=>{if(commit(()=>{db=v.data;},'백업 데이터를 불러왔습니다.')){project='all';closeModal();render();}});}catch(err){toast(err.message||'백업 파일을 읽을 수 없습니다.');}};input.click();},
 reset:()=>modal('샘플 데이터로 초기화할까요?','<p style="line-height:1.9">현재 브라우저에서 입력한 데이터와 첨부파일이 샘플 데이터로 바뀝니다. 필요하면 먼저 전체 데이터를 백업해 주세요.</p>',formButtons('샘플로 초기화'),()=>{if(commit(()=>{db=seed();},'샘플 데이터로 초기화했습니다.')){project='all';closeModal();render();}})
};
document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return;}const action=e.target.closest('[data-action]');if(action){actions[action.dataset.action]?.(action);return;}const issue=e.target.closest('[data-issue]');if(issue){issueDetail(issue.dataset.issue);return;}const task=e.target.closest('[data-task]');if(task){taskForm(task.dataset.task);return;}const p=e.target.closest('[data-project]');if(p){view='projects';detailProject=p.dataset.project;render();window.scrollTo({top:0});}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="button"][tabindex]')){e.preventDefault();e.target.click();}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
render();if(loadWarning)toast(loadWarning);
